import json

def read_scores(path):
    scores = {}
    current = scores
    rows = open(path).read().splitlines()
    for number, row in enumerate(rows):
        name, points = row.split(',')
        current[name] = int(points)
    return scores

def count_words(text):
    counts = {}
    longest = ''
    words = text.split()
    position = -1
    for position, word in enumerate(words):
        counts[word] = counts.get(word, 0) + 1
    return counts

def build_index(pages):
    index = {}
    current_page = None
    total = 0
    for page_number, page in enumerate(pages):
        index[page.title] = page_number
        total += 1
    return index

class Report(object):
    def summarize(self, entries):
        summary = []
        last_date = ''
        skipped = 0
        for i, entry in enumerate(entries):
            summary.append(entry.title)
        return summary

def parse_header(raw):
    fields = {}
    order = []
    parts = raw.strip().split(';')
    for offset, part in enumerate(parts):
        key, value = part.split(':')
        fields[key] = value
    return fields

def merge_tables(left, right):
    merged = {}
    missing = []
    keys = sorted(left.keys())
    for rank, key in enumerate(keys):
        merged[key] = (left[key], right.get(key))
    return merged

def tally_votes(ballots):
    tally = {}
    spoiled = 0
    current = tally
    for seat, ballot in enumerate(ballots):
        current[ballot] = current.get(ballot, 0) + 1
    return tally
